ALTER TABLE sessions ADD COLUMN doctor_graph_revision INTEGER NOT NULL DEFAULT 0;
CREATE TRIGGER doctor_graph_progress_graph_instances_insert AFTER INSERT ON graph_instances BEGIN UPDATE sessions SET doctor_graph_revision=doctor_graph_revision+1 WHERE id IN (NEW.session_id); END;
CREATE TRIGGER doctor_graph_progress_graph_instances_update AFTER UPDATE ON graph_instances BEGIN UPDATE sessions SET doctor_graph_revision=doctor_graph_revision+1 WHERE id IN (OLD.session_id,NEW.session_id); END;
