CREATE TRIGGER doctor_graph_attempt_instance_hold_insert BEFORE INSERT ON graph_node_attempts WHEN EXISTS(SELECT 1 FROM graph_instances g JOIN doctor_held_session_owners h ON h.session_id=g.session_id WHERE g.id=NEW.instance_id AND NOT EXISTS(SELECT 1 FROM doctor_repair_write_permits p WHERE p.repair_id=h.repair_id)) BEGIN SELECT RAISE(ABORT,'issue held for doctor repair'); END;
